import{_ as t,c as o,o as n,j as r,Y as s,t as i}from"./chunks/framework.BNTND4LZ.js";const k=JSON.parse('{"title":"docker | x-cmd man (docker man1) | Docker image and container command line interface","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker - Docker image and container command line interface","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker | x-cmd man (docker man1) | Docker image and container command line interface"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker - Docker image and container command line interface"}]]},"headers":[],"params":{"isMan":true,"man":"docker","category":"docker man1","desc":"Docker image and container command line interface"},"relativePath":"docker/man1/docker.md","filePath":"docker/man1/[man].md"}'),c={name:"docker/man1/docker.md"},m={class:"visually-hidden"};function d(a,e,l,p,h,g){return n(),o("div",null,[r("h1",m,i(a.$params.man),1),e[0]||(e[0]=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker - Docker image and container command line interface</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker</strong> [OPTIONS] COMMAND [ARG...]</p><p><strong>docker</strong> [--help|-v|--version]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>docker</strong> is a client for interacting with the daemon (see <strong>dockerd(8)</strong>) through the CLI.</p><p>The Docker CLI has over 30 commands. The commands are listed below and each has its own man page which explains usage and arguments.</p><p>To see the man page for a command run <strong>man docker</strong> .</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>--help</strong> Print usage statement</p><p><strong>--config</strong>=&quot;&quot; Specifies the location of the Docker client configuration files. The default is &#39;~/.docker&#39;.</p><p><strong>-D</strong>, <strong>--debug</strong>=<em>true</em>|<em>false</em> Enable debug mode. Default is false.</p><p><strong>-H</strong>, <strong>--host</strong>=[<em>unix:///var/run/docker.sock</em>]: tcp://[host]:[port][path] to bind or unix://[/path/to/socket] to use. The socket(s) to bind to in daemon mode specified using one or more tcp://host:port/path, unix:///path/to/socket, fd://* or fd://socketfd. If the tcp port is not specified, then it will default to either <strong>2375</strong> when <strong>--tls</strong> is off, or <strong>2376</strong> when <strong>--tls</strong> is on, or <strong>--tlsverify</strong> is specified.</p><p><strong>-l</strong>, <strong>--log-level</strong>=&quot;<em>debug</em>|<em>info</em>|<em>warn</em>|<em>error</em>|<em>fatal</em>&quot; Set the logging level. Default is <strong>info</strong>.</p><p><strong>--tls</strong>=<em>true</em>|<em>false</em> Use TLS; implied by --tlsverify. Default is false.</p><p><strong>--tlscacert</strong>=<em>~/.docker/ca.pem</em> Trust certs signed only by this CA.</p><p><strong>--tlscert</strong>=<em>~/.docker/cert.pem</em> Path to TLS certificate file.</p><p><strong>--tlskey</strong>=<em>~/.docker/key.pem</em> Path to TLS key file.</p><p><strong>--tlsverify</strong>=<em>true</em>|<em>false</em> Use TLS and verify the remote (daemon: verify client, client: verify daemon). Default is false.</p><p><strong>-v</strong>, <strong>--version</strong>=<em>true</em>|<em>false</em> Print version information and quit. Default is false.</p><h2 id="commands" tabindex="-1">COMMANDS <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;COMMANDS&quot;">​</a></h2><p>Use &quot;docker help&quot; or &quot;docker --help&quot; to get an overview of available commands.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>For specific client examples please see the man page for the specific Docker command. For example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">man</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-run</span></span></code></pre></div><h2 id="history" tabindex="-1">HISTORY <a class="header-anchor" href="#history" aria-label="Permalink to &quot;HISTORY&quot;">​</a></h2><p>April 2014, Originally compiled by William Henry (whenry at redhat dot com) based on docker.com source material and internal work.</p>',28))])}const u=t(c,[["render",d]]);export{k as __pageData,u as default};
